'use strict';
// ================================================================ detailed tree models (near the camera) — far trees keep the light instanced shapes
const TREE2={R:95,cx:1e9,cz:1e9,sets:{},u:{uTime:{value:0},uWind:{value:1}}};
function _tg(g){return g.index?g.toNonIndexed():g;}
function tgMerge(parts){// parts: [geometry, colourFn(x,y,z)->[r,g,b], normalCentre|null]
  let n=0;for(const [g] of parts)n+=g.attributes.position.count;const P=new Float32Array(n*3),C=new Float32Array(n*3),Nn=new Float32Array(n*3);let o=0;
  for(const [g0,cf,nc] of parts){const g=_tg(g0);if(!nc)g.computeVertexNormals();const p=g.attributes.position,nr=g.attributes.normal;
    for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);P[(o+i)*3]=x;P[(o+i)*3+1]=y;P[(o+i)*3+2]=z;const c=cf(x,y,z,i);C[(o+i)*3]=c[0];C[(o+i)*3+1]=c[1];C[(o+i)*3+2]=c[2];
      if(nc){let nx=x-nc[0],ny=(y-nc[1])*1.3+.35,nz=z-nc[2];const fx=nr?nr.getX(i):0,fy=nr?nr.getY(i):1,fz=nr?nr.getZ(i):0;nx=nx*.75+fx*.25;ny=ny*.75+fy*.25;nz=nz*.75+fz*.25;const l=Math.hypot(nx,ny,nz)||1;Nn[(o+i)*3]=nx/l;Nn[(o+i)*3+1]=ny/l;Nn[(o+i)*3+2]=nz/l;}
      else{Nn[(o+i)*3]=nr.getX(i);Nn[(o+i)*3+1]=nr.getY(i);Nn[(o+i)*3+2]=nr.getZ(i);}}
    o+=p.count;}
  const m=new THREE.BufferGeometry();m.setAttribute('position',new THREE.BufferAttribute(P,3));m.setAttribute('color',new THREE.BufferAttribute(C,3));m.setAttribute('normal',new THREE.BufferAttribute(Nn,3));return m;}
function jitterGeo(g,r,amt,sx,sy,sz){g=_tg(g);const p=g.attributes.position;const key=(x,y,z)=>Math.round(x*97)+','+Math.round(y*97)+','+Math.round(z*97);const off=new Map();
  for(let i=0;i<p.count;i++){const k=key(p.getX(i),p.getY(i),p.getZ(i));if(!off.has(k))off.set(k,1+(r()-.5)*2*amt);const f=off.get(k);p.setXYZ(i,p.getX(i)*f*sx,p.getY(i)*f*sy,p.getZ(i)*f*sz);}return g;}
function placed(g,x,y,z,rx=0,ry=0,rz=0){g=g.clone();g.rotateX(rx);g.rotateY(ry);g.rotateZ(rz);g.translate(x,y,z);return g;}
function branch(x0,y0,z0,x1,y1,z1,r0,r1){const dx=x1-x0,dy=y1-y0,dz=z1-z0,L=Math.hypot(dx,dy,dz);const g=new THREE.CylinderGeometry(r1,r0,L,5);g.translate(0,L/2,0);
  const q=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(dx/L,dy/L,dz/L));g.applyMatrix4(new THREE.Matrix4().makeRotationFromQuaternion(q));g.translate(x0,y0,z0);return g;}
const BARK=(r,g,b)=>(x,y,z)=>{const v=.85+.15*Math.sin(y*9+x*13);return [r*v,g*v,b*v];};
function makeOak(seed){const r=mulberry(seed);const T=[],C=[];const h=1.5+r()*.5;
  T.push([branch(0,-.2,0,0,h,0,.32,.22),BARK(.36,.26,.17)]);
  for(let i=0;i<4;i++){const a=i/4*TAU+r()*.8;const fx=Math.cos(a)*.42,fz=Math.sin(a)*.42;T.push([branch(fx*.25,-.18,fz*.25,fx,-.05,fz,.16,.05),BARK(.33,.24,.16)]);}// root flare
  const ends=[[0,h+1.3,0]];for(let i=0;i<4;i++){const a=i/4*TAU+r()*.9,L=.9+r()*.5,ey=h+.5+r()*.7;const ex=Math.cos(a)*L,ez=Math.sin(a)*L;T.push([branch(0,h-.15,0,ex,ey,ez,.15,.07),BARK(.36,.26,.17)]);ends.push([ex*1.15,ey+.35,ez*1.15]);}
  const cen=[0,h+1.1,0];
  for(const [ex,ey,ez] of ends){const s=.85+r()*.35;const g=jitterGeo(new THREE.IcosahedronGeometry(1,1),r,.14,s*1.05,s*.82,s);const shade=.88+r()*.18,hue=r();
    C.push([placed(g,ex,ey,ez,0,r()*6,0),(x,y,z)=>{const t=clamp((y-(h+.2))/2.1,0,1);const v=(.55+.55*t)*shade;return [v*(.96+hue*.08),v,v*(.95-hue*.05)];},cen]);}
  for(let i=0;i<3;i++){const a=r()*TAU,s=.6+r()*.3;const g=jitterGeo(new THREE.IcosahedronGeometry(1,1),r,.15,s,s*.8,s);C.push([placed(g,Math.cos(a)*.6,h+1.6+r()*.5,Math.sin(a)*.6),(x,y,z)=>{const v=.95+((y-h)/3)*.25;return [v,v,v*.96];},cen]);}
  return {trunk:tgMerge(T),crown:tgMerge(C)};}
function makePine(seed){const r=mulberry(seed);const T=[],C=[];const H=4.6+r()*1.2;
  T.push([branch(0,-.2,0,0,H*.55,0,.2,.12),BARK(.3,.21,.14)]);
  const tiers=5+Math.floor(r()*2);for(let i=0;i<tiers;i++){const f=i/(tiers-1);const rad=(1.45-f*1.05)*(.92+r()*.16),y0=.55+f*(H-1.5),hh=1.1+(1-f)*.5;
    const g=_tg(new THREE.ConeGeometry(rad,hh,9,2,false));const p=g.attributes.position;// droop the skirt tips, jag the rim
    for(let k=0;k<p.count;k++){const y=p.getY(k);if(y<-hh/2+.01){const a=Math.atan2(p.getZ(k),p.getX(k));const j=(Math.round(a/(TAU/9))%2===0)?1.12:.86;p.setXYZ(k,p.getX(k)*j,y-(j>1?.16:0),p.getZ(k)*j);}}
    const sh=.62+f*.45+(r()-.5)*.06;C.push([placed(g,0,y0+hh/2,0,0,r()*TAU,0),(x,y,z)=>{const rim=Math.hypot(x,z)/rad;const v=sh*(1.02-rim*.25);return [v*.94,v,v*.97];},null]);}
  C.push([placed(new THREE.ConeGeometry(.22,.7,6),0,H+.15,0),()=>[1.1,1.12,1.08],null]);
  return {trunk:tgMerge(T),crown:tgMerge(C)};}
function makeBirch(seed){const r=mulberry(seed);const T=[],C=[];const H=3.4+r()*.8,lean=(r()-.5)*.25;
  const bark=(x,y,z)=>{const m=Math.sin(y*11+Math.sin(x*30)*2)>.75?.3:1;return [.86*m,.84*m,.8*m];};
  T.push([branch(0,-.2,0,lean,H,lean*.5,.15,.07),bark]);
  for(let i=0;i<3;i++){const a=r()*TAU,y=H*.55+i*.35;T.push([branch(lean*y/H,y,lean*.5*y/H,Math.cos(a)*.6,y+.6,Math.sin(a)*.6,.05,.02),bark]);}
  const cen=[lean*.8,H-.3,0];
  for(let i=0;i<6;i++){const a=i/6*TAU+r(),d=.25+r()*.45,y=H*.55+r()*(H*.5);const s=.38+r()*.22;const g=jitterGeo(new THREE.IcosahedronGeometry(1,1),r,.14,s,s*1.45,s);
    C.push([placed(g,lean*y/H+Math.cos(a)*d,y,Math.sin(a)*d),(x,y2,z)=>{const v=.72+.4*clamp((y2-H*.5)/(H*.6),0,1);return [v,v,v*.95];},cen]);}
  return {trunk:tgMerge(T),crown:tgMerge(C)};}
function makeWillow(seed){const r=mulberry(seed);const T=[],C=[];const h=1.5;
  T.push([branch(0,-.2,0,0,h,0,.36,.24),BARK(.34,.27,.18)]);for(let i=0;i<3;i++){const a=i/3*TAU+r();T.push([branch(0,h-.1,0,Math.cos(a)*.8,h+.7,Math.sin(a)*.8,.14,.07),BARK(.34,.27,.18)]);}
  const cen=[0,h+.8,0];const dome=jitterGeo(new THREE.IcosahedronGeometry(1,1),r,.12,1.55,.85,1.55);C.push([placed(dome,0,h+.95,0),(x,y,z)=>{const v=.8+.3*clamp((y-h)/1.6,0,1);return [v,v,v];},cen]);
  for(let i=0;i<18;i++){const a=i/18*TAU+r()*.2,d=1.15+r()*.35,L=1.3+r()*.7;const g=new THREE.ConeGeometry(.2+r()*.08,L,4);g.rotateX(PI);C.push([placed(g,Math.cos(a)*d,h+.75-L/2+.3,Math.sin(a)*d,0,r()*6,0),(x,y,z)=>{const v=.62+.35*clamp((y-.2)/2,0,1);return [v*.98,v,v*.9];},cen]);}
  return {trunk:tgMerge(T),crown:tgMerge(C)};}
function makeBush(seed){const r=mulberry(seed);const C=[];const cen=[0,.35,0];for(let i=0;i<4;i++){const a=r()*TAU,d=r()*.35,s=.35+r()*.25;const g=jitterGeo(new THREE.IcosahedronGeometry(1,1),r,.16,s,s*.75,s);
    C.push([placed(g,Math.cos(a)*d,.3+r()*.2,Math.sin(a)*d),(x,y,z)=>{const v=.7+.45*clamp(y/.8,0,1);return [v,v,v*.95];},cen]);}
  if(r()<.5)for(let i=0;i<5;i++){const a=r()*TAU;C.push([placed(new THREE.IcosahedronGeometry(.07,0),Math.cos(a)*.4,.45+r()*.3,Math.sin(a)*.4),()=>[2.2,.6,.5],null]);}// berries
  return {trunk:null,crown:tgMerge(C)};}
function makeRock(seed){const r=mulberry(seed);const g=jitterGeo(new THREE.IcosahedronGeometry(1,1),r,.22,1.05,.62,.9);
  const C=[[g,(x,y,z)=>{const n=Math.sin(x*7+z*5)*.5+.5;const lich=y>.25&&r()<.35;const v=.82+n*.22;return lich?[v*.78,v*.88,v*.62]:[v,v*.98,v*.94];},null]];
  return {trunk:null,crown:tgMerge(C)};}
// materials
TREE2.trunkMat=new THREE.MeshStandardMaterial({vertexColors:true,flatShading:true,roughness:.95});
TREE2.crownMat=new THREE.MeshStandardMaterial({vertexColors:true,flatShading:false,roughness:.85});
TREE2.crownMat.onBeforeCompile=sh=>{sh.uniforms.uTime=TREE2.u.uTime;sh.uniforms.uWind=TREE2.u.uWind;
  sh.vertexShader='uniform float uTime,uWind;\n'+sh.vertexShader.replace('#include <begin_vertex>',`#include <begin_vertex>
  {vec3 ip=vec3(instanceMatrix[3][0],instanceMatrix[3][1],instanceMatrix[3][2]);float k=max(position.y-.6,0.)*.05*uWind;
   transformed.x+=sin(uTime*1.3+ip.x*.21+ip.z*.13)*k+sin(uTime*2.9+position.y*2.+ip.x)*k*.35;transformed.z+=cos(uTime*1.1+ip.z*.19)*k*.7;}`);
  sh.fragmentShader=sh.fragmentShader.replace('#include <lights_fragment_begin>','#include <lights_fragment_begin>\n');};
TREE2.crownMat.customProgramCacheKey=()=>'crown';
TREE2.rockMat=new THREE.MeshStandardMaterial({vertexColors:true,flatShading:true,roughness:.92});
// species -> variants
TREE2.kinds={0:[makePine,3],1:[makeOak,3],2:[makeBirch,2],3:[makeWillow,2],4:[makeRock,3],5:[makeBush,2]};
for(const k in TREE2.kinds){const [fn,n]=TREE2.kinds[k];TREE2.sets[k]=[];for(let v=0;v<n;v++){const m=fn(1000+(+k)*31+v*7);const e={};
    if(m.trunk){e.trunk=new THREE.InstancedMesh(m.trunk,TREE2.trunkMat,64);}e.crown=new THREE.InstancedMesh(m.crown,+k===4?TREE2.rockMat:TREE2.crownMat,64);
    for(const kk of ['trunk','crown'])if(e[kk]){const im=e[kk];im.setColorAt(0,new THREE.Color());im.count=0;im.castShadow=true;im.receiveShadow=true;im.frustumCulled=false;im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);scene.add(im);}
    e.n=0;TREE2.sets[k].push(e);}}
function t2Ensure(e,kk,n){const im=e[kk];if(n<=im.instanceMatrix.count)return im;const nm=new THREE.InstancedMesh(im.geometry,im.material,Math.ceil(n*1.4)+32);nm.setColorAt(0,new THREE.Color());nm.castShadow=true;nm.receiveShadow=true;nm.frustumCulled=false;
  scene.remove(im);im.dispose&&im.dispose();scene.add(nm);e[kk]=nm;return nm;}
const _t2o=new THREE.Object3D(),_t2c=new THREE.Color(),_t2w=new THREE.Color(1,1,1);
function t2Begin(){for(const k in TREE2.sets)for(const e of TREE2.sets[k])e.list=[];}
function t2Crown(t){// crown tint, or null when bare
  switch(t.t){
    case 0:{const g=treeColor(t,t.c>.8?0x2f5a3a:0x2e5730,0).clone().multiplyScalar(1.12);if(WINTER>.5)g.lerp(_snowC,.42);return g;}
    case 1:{if(WINTER>.5)return null;const au=t.c>.955;return seasonal2(treeColor(t,au?0xb8732c:0x4c7a2f,0).clone(),t).multiplyScalar(1.12);}
    case 2:{if(WINTER>.5)return null;return seasonal2(treeColor(t,t.c>.93?0xc9b03a:0x7fa246,0).clone(),t,1).multiplyScalar(1.05);}
    case 3:{if(WINTER>.5)return null;return seasonal2(treeColor(t,0x8aa548,0).clone(),t,1);}
    case 4:{const g=treeColor(t,0x8a857c,0).clone();if(SNOWF>.4)g.lerp(_snowC,.5);return g;}
    case 5:{if(WINTER>.5)return null;return treeColor(t,0x547d33,0).clone().multiplyScalar(1.1);}}
  return null;}
function seasonal2(g,t,yl){if(AUTUMN>.01){_tc2.setHex(yl?0xd8b030:(t.c<.33?0xc0502a:t.c<.66?0xd88a2a:0xc9a032));g.lerp(_tc2,AUTUMN*(.55+t.c*.45));}return g;}
function t2Put(t,y,s){const set=TREE2.sets[t.t];if(!set)return false;const e=set[Math.floor(t.c*997+t.r*31)%set.length];e.list.push([t.x,y+(t.t===4?.1*s:0),t.z,t.r,s*(t.t===4?1.05:1),t2Crown(t),.85+t.c*.3]);return true;}
function t2End(){for(const k in TREE2.sets)for(const e of TREE2.sets[k]){const L=e.list,n=L.length;
    const cr=t2Ensure(e,'crown',n),tr=e.trunk?t2Ensure(e,'trunk',n):null;let nc=0;
    for(let i=0;i<n;i++){const [x,y,z,ry,s,cc,tv]=L[i];_t2o.position.set(x,y,z);_t2o.rotation.set(0,ry,0);_t2o.scale.set(s,s,s);_t2o.updateMatrix();
      if(tr){tr.setMatrixAt(i,_t2o.matrix);tr.setColorAt(i,_t2c.setRGB(tv,tv*.97,tv*.94));}
      if(cc){cr.setMatrixAt(nc,_t2o.matrix);cr.setColorAt(nc,cc);nc++;}}
    cr.count=nc;cr.instanceMatrix.needsUpdate=true;if(cr.instanceColor)cr.instanceColor.needsUpdate=true;
    if(tr){tr.count=n;tr.instanceMatrix.needsUpdate=true;if(tr.instanceColor)tr.instanceColor.needsUpdate=true;}}}
