function latheZ(prof,seg,sx,sy,colFn){const g=new THREE.LatheGeometry(prof.map(([z,r])=>new THREE.Vector2(r,z)),seg);g.rotateX(PI/2);g.rotateZ(PI/seg);g.scale(sx,sy,1);
  const ng=g.index?g.toNonIndexed():g;const p=ng.attributes.position,c=new Float32Array(p.count*3);for(let i=0;i<p.count;i++){const k=colFn(p.getX(i),p.getY(i),p.getZ(i));c[i*3]=k[0];c[i*3+1]=k[1];c[i*3+2]=k[2];}
  ng.setAttribute('color',new THREE.BufferAttribute(c,3));ng.computeVertexNormals();return ng;}
function mergeG(list){let n=0;for(const g of list)n+=g.attributes.position.count;const P=new Float32Array(n*3),C=new Float32Array(n*3);let o=0;
  for(const g of list){P.set(g.attributes.position.array,o*3);C.set(g.attributes.color.array,o*3);o+=g.attributes.position.count;}
  const m=new THREE.BufferGeometry();m.setAttribute('position',new THREE.BufferAttribute(P,3));m.setAttribute('color',new THREE.BufferAttribute(C,3));m.computeVertexNormals();return m;}
