    {const M=_am.clone().multiply(aloc(0,byy*.3,hz,nk,0,0,1,1,1));aput('neck',M.clone().multiply(aloc(0,0,0,0,0,0,.07,S2.neck||.3,.08)),a.col);
      const H2=M.clone().multiply(aloc(0,S2.neck||.3,0,-nk+.2+(graze?.2:0),0,0,1,1,1));aput('head',H2.clone().multiply(aloc(0,0,.06,0,0,0,...(S2.head||[.1,.1,.18]))),a.col);}
